enum DesktopPlatform { linuxGtk, linuxQt, windowsWin32, windowsModern, macosAppKit, macosSwiftUI, classic }
enum DesktopEventType { windowCreate, windowClose, windowMove, windowResize, focusIn, focusOut, keyDown, keyUp, textInput, pointerMove, pointerDown, pointerUp, wheel, touchBegin, touchUpdate, touchEnd, gesture, dragBegin, dragUpdate, dragEnd, menuCommand, displayChange, themeChange, quit }
class DesktopEvent { final DesktopEventType type; final int timestampNs; final String deviceId, windowId, key, text; final double x,y,dx,dy; final int modifiers,buttons; const DesktopEvent({required this.type,required this.timestampNs,required this.deviceId,this.windowId='',this.x=0,this.y=0,this.dx=0,this.dy=0,this.modifiers=0,this.buttons=0,this.key='',this.text=''}); }
class EventRouter { final Map<DesktopEventType,void Function(DesktopEvent)> _handlers={}; void on(DesktopEventType type,void Function(DesktopEvent) handler)=>_handlers[type]=handler; void dispatch(DesktopEvent event)=>_handlers[event.type]?.call(event); }
